function persistDrafts(drafts){try{localStorage.setItem(draftStorageKey,JSON.stringify(drafts));return true}catch{showToast('Návrh se nepodařilo uložit v tomto prohlížeči.');return false}}
function renderDrafts(){
  const drafts=Object.values(draftData).sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0));
  const groups=[['draft-list',drafts.filter(item=>item.state!=='complete'),'Zatím tu nemáš žádný rozpracovaný návrh.'],['completed-list',drafts.filter(item=>item.state==='complete'),'Zatím tu nemáš žádný hotový návrh.']];
  document.getElementById('draft-count').textContent=String(groups[0][1].length).padStart(2,'0');
  document.getElementById('completed-count').textContent=String(groups[1][1].length).padStart(2,'0');
  for(const [listId,items,emptyText] of groups){const list=document.getElementById(listId);list.replaceChildren();if(!items.length){const empty=document.createElement('p');empty.className='draft-empty';empty.textContent=emptyText;list.append(empty);continue}for(const draft of items){
    const card=document.createElement('article');card.className='draft-card';card.dataset.draftCard=draft.id;
    const thumb=document.createElement('span');thumb.className='draft-thumb';if(typeof draft.thumbnail==='string'&&draft.thumbnail.startsWith('data:image/jpeg;base64,'))thumb.style.backgroundImage=`url("${draft.thumbnail}")`;
    const copy=document.createElement('span');copy.className='draft-copy';const title=document.createElement('b');title.textContent=draft.title||'Bez názvu';const detail=document.createElement('small');const song=draft.fields?.['track-select']||'Bez skladby',format=formatMap[draft.format]?.title||'Story';detail.textContent=`${song} · ${format} · ${new Date(draft.updatedAt||Date.now()).toLocaleDateString('cs-CZ')}`;copy.append(title,detail);
    const status=document.createElement('span');status.className='draft-status';status.textContent=draft.state==='complete'?'HOTOVO':'ROZPRACOVÁNO';
    const actions=document.createElement('span');actions.className='draft-actions';const open=document.createElement('button');open.type='button';open.dataset.draftOpen=draft.id;open.textContent='POKRAČOVAT';const remove=document.createElement('button');remove.type='button';remove.className='delete-action';remove.dataset.draftDelete=draft.id;remove.textContent='SMAZAT';actions.append(open,remove);card.append(thumb,copy,status,actions);list.append(card);
  }}
}
function saveDraft(completed=false){const id=currentDraftKey||`draft-${Date.now()}-${Math.random().toString(36).slice(2,8)}`;const fields=Object.fromEntries(draftFieldIds.map(field=>[field,document.getElementById(field).value]));const asset=selectedAsset();const draft={id,state:completed?'complete':'draft',title:fields['post-headline'].trim()||fields['main-headline'].trim()||asset?.name||'Nový návrh',fields,format:currentFormat,align:document.querySelector('[data-align].selected')?.dataset.align||'left',filters:Array.from(document.querySelectorAll('[data-video-filter]:checked')).map(input=>input.dataset.videoFilter),asset:asset?{name:asset.name,type:asset.type,src:asset.src,relativePath:asset.relativePath||'',source:asset.source||''}:null,startFrame:selectedStartFrame,endFrame:selectedEndFrame,thumbnail:draftThumbnail(),updatedAt:Date.now()};const next=Object.values(draftData).filter(item=>item.id!==id).concat(draft);if(!persistDrafts(next))return;draftData[id]=draft;currentDraftKey=id;renderDrafts();showToast(completed?'Hotový návrh uložen do Obsahu studia.':'Návrh uložen mezi rozpracované.')}
function loadDraft(key){const draft=draftData[key];if(!draft)return;setPreviewPlayback(false);currentDraftKey=key;showView('studio');for(const field of draftFieldIds){const element=document.getElementById(field);if(element&&typeof draft.fields?.[field]==='string')element.value=draft.fields[field]}for(const id of ['main-headline-size','headline-size','caption-size','track-size'])document.getElementById(`${id}-value`).value=`${document.getElementById(id).value} %`;document.getElementById('char-count').textContent=`${document.getElementById('caption').value.length} / 500`;const track=document.getElementById('track-select').value;document.getElementById('track-hint').textContent=track?`Odkaz: Spotify · Atari Terror — ${track}`:'Výběr skladby je nepovinný.';document.getElementById('copy-track').disabled=!track;document.querySelectorAll('[data-align]').forEach(button=>{const active=button.dataset.align===draft.align;button.classList.toggle('selected',active);button.setAttribute('aria-pressed',String(active))});document.querySelectorAll('[data-video-filter]').forEach(input=>input.checked=Boolean(draft.filters?.includes(input.dataset.videoFilter)));const asset=draft.asset;if(asset?.src&&['image','video'].includes(asset.type)){let index=assets.findIndex(item=>item.relativePath&&item.relativePath===asset.relativePath||item.src===asset.src);if(index<0){assets.push({...asset,tag:asset.type==='video'?'VIDEO':'FOTO'});index=assets.length-1}selected=index}else selected=-1;renderAssetGrid();const formatButton=Array.from(document.querySelectorAll('.format-tab')).find(button=>button.dataset.format===draft.format);formatButton?.click();if(asset?.type==='video'){selectedStartFrame=Number(draft.startFrame)||0;selectedEndFrame=Number(draft.endFrame)||5*PREVIEW_FPS;clipSelectionLoaded=true;saveClipSelection();restartPreviewClip()}else{syncFrameScrubbers();refreshPreview('PŘIPRAVUJI NÁVRH',8)}closeActionModal();showToast('Rozpracovaný návrh otevřen v editoru.')}
function deleteDraft(key){const draft=draftData[key];if(!draft)return;const next=Object.values(draftData).filter(item=>item.id!==key);if(!persistDrafts(next))return;delete draftData[key];if(currentDraftKey===key)currentDraftKey=null;renderDrafts();showToast(`Návrh „${draft.title}“ byl smazán.`)}
async function loadRemoteLibrary(){
  const status=document.getElementById('library-source-status');
  if(status)status.textContent='Načítám obsah složek z GitHubu…';
  try{
    const response=await fetch(`https://api.github.com/repos/${githubRepository}/git/trees/main?recursive=1`,{headers:githubToken?githubHeaders():{Accept:'application/vnd.github+json'}});
    if(!response.ok){let detail='';try{detail=(await response.json()).message||''}catch{}throw new Error(detail||`GitHub vrátil chybu ${response.status}.`)}
    const tree=await response.json();if(tree.truncated)throw new Error('Seznam souborů repozitáře je příliš velký; zkus načtení znovu.');
    const folders=libraryDirectories.map(name=>({name,path:`GitHub / ${githubRepository}/${name}`,files:[]}));
    for(const entry of tree.tree||[]){if(entry.type!=='blob'||entry.path.endsWith('/.gitkeep'))continue;const folderName=entry.path.split('/')[0],folder=folders.find(item=>item.name===folderName);if(!folder)continue;const name=entry.path.split('/').pop(),encodedPath=entry.path.split('/').map(encodeURIComponent).join('/');folder.files.push({name,path:entry.path,sha:entry.sha,url:`https://raw.githubusercontent.com/${githubRepository}/main/${encodedPath}`,type:mediaType(name),size:entry.size})}
    remoteLibrary=folders;renderFolderList();renderFolderList('picker-folder-list');if(status){const count=remoteLibrary.reduce((sum,folder)=>sum+folder.files.length,0);status.textContent=`Načteno z GitHubu · ${count} souborů v ${remoteLibrary.length} složkách.`}updateCounts()
  }catch(error){if(status)status.textContent=`Knihovnu se nepodařilo načíst: ${error.message}`;showToast(`Načtení knihovny selhalo: ${error.message}`)}
}
function mediaType(name){const extension=name.split('.').pop().toLowerCase();if(['mp4','mov','m4v','webm','mkv'].includes(extension))return'video';if(['jpg','jpeg','png','gif','webp','avif'].includes(extension))return'image';if(['txt','md','srt','vtt','json','csv'].includes(extension))return'text';return'file'}
function safeFilePath(folder,name){return`${folder}/${name.split('/').map(encodeURIComponent).join('/')}`}
function githubHeaders(){return{Accept:'application/vnd.github+json',Authorization:`Bearer ${githubToken}`,'X-GitHub-Api-Version':'2022-11-28'}}
function openGithubConnect(action){pendingGithubAction=action;const modal=document.getElementById('github-connect-modal');modal.hidden=false;modal.setAttribute('aria-hidden','false');document.getElementById('github-token-input').focus()}
function closeGithubConnect(){document.getElementById('github-connect-modal').hidden=true;document.getElementById('github-token-input').value=''}
async function uploadLibraryFile(folder,file){if(!githubToken){openGithubConnect(()=>uploadLibraryFile(folder,file));return}if(file.size>50*1024*1024){showToast('Soubor je větší než 50 MB. Pro takto velká videa je potřeba Git LFS.');return}try{const existing=remoteLibrary.find(item=>item.name===folder)?.files.find(item=>item.name===file.name);if(existing&&!confirm(`„${file.name}“ už existuje v ${folder}. Chceš ho na GitHubu nahradit?`))return;showToast(`Nahrávám ${file.name} do ${folder}…`);const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let offset=0;offset<bytes.length;offset+=0x8000)binary+=String.fromCharCode(...bytes.subarray(offset,offset+0x8000));const content=btoa(binary);const path=safeFilePath(folder,file.name);const payload={message:`Upload ${file.name} to ${folder}`,content};if(existing)payload.sha=existing.sha;const response=await fetch(`${githubApiRoot}/${path}`,{method:'PUT',headers:{...githubHeaders(),'Content-Type':'application/json'},body:JSON.stringify(payload)});const result=await response.json();if(!response.ok)throw new Error(result.message||`GitHub vrátil chybu ${response.status}.`);await loadRemoteLibrary();showToast(`Nahráno do GitHubu: ${file.name}`)}catch(error){if(/401|403|Bad credentials|Resource not accessible/i.test(error.message)){githubToken='';document.getElementById('github-connect').textContent='PŘIPOJIT GITHUB ↗'}showToast(`Nahrávání selhalo: ${error.message}`)}}
async function deleteLibraryFile(folder,file){if(!githubToken){openGithubConnect(()=>deleteLibraryFile(folder,file));return}if(!confirm(`Opravdu smazat „${file.name}“ ze složky ${folder} na GitHubu?`))return;try{const response=await fetch(`${githubApiRoot}/${safeFilePath(folder,file.name)}`,{method:'DELETE',headers:{...githubHeaders(),'Content-Type':'application/json'},body:JSON.stringify({message:`Delete ${file.name} from ${folder}`,sha:file.sha})});const result=await response.json();if(!response.ok)throw new Error(result.message||`GitHub vrátil chybu ${response.status}.`);const assetIndex=assets.findIndex(asset=>asset.relativePath===file.path||asset.name===file.name&&asset.source==='github');if(assetIndex>=0){if(selected===assetIndex){setPreviewPlayback(false);video.pause()}assets.splice(assetIndex,1);if(selected>=assets.length)selected=Math.max(0,assets.length-1);renderAssetGrid()}await loadRemoteLibrary();showToast(`Smazáno z GitHubu: ${file.name}`)}catch(error){showToast(`Mazání selhalo: ${error.message}`)}}
function renderFolderList(targetId='folder-list'){
  const container=document.getElementById(targetId);if(!container)return;container.replaceChildren();const canManage=targetId==='folder-list';
  remoteLibrary.forEach(folder=>{const card=document.createElement('section');card.className='folder-card';const head=document.createElement('div');head.className='folder-card-head';const icon=document.createElement('span');icon.className='folder-icon';icon.textContent='▰';const label=document.createElement('div');const title=document.createElement('strong');title.textContent=folder.name;const path=document.createElement('small');path.textContent=folder.path;label.append(title,path);const count=document.createElement('span');count.className='folder-count';count.textContent=`${String(folder.files.length).padStart(2,'0')} SOUBORŮ`;head.append(icon,label,count);if(canManage){const upload=document.createElement('button');upload.type='button';upload.className='button button-outline folder-upload';upload.textContent='＋ NAHRÁT';upload.dataset.folderUpload=folder.name;const input=document.createElement('input');input.type='file';input.hidden=true;input.dataset.folderFile=folder.name;upload.addEventListener('click',()=>input.click());input.addEventListener('change',()=>{const file=input.files?.[0];if(file)uploadLibraryFile(folder.name,file);input.value=''});head.append(upload,input)}card.append(head);const list=document.createElement('div');list.className='folder-files';folder.files.forEach(file=>{if(!canManage&&!['video','image'].includes(file.type))return;const assetIndex=assets.findIndex(asset=>asset.relativePath===file.path||asset.src===file.url);const row=document.createElement('button');row.type='button';row.className='folder-file'+(assetIndex>=0?' loaded':'');row.textContent=file.name;row.title=['video','image'].includes(file.type)?'Načíst tento soubor do editoru':'Soubor není obraz ani video';row.dataset.assetName=file.name;row.dataset.assetPath=file.path;row.dataset.assetUrl=file.url;row.dataset.assetType=file.type;row.dataset.folder=folder.name;row.dataset.assetIndex=String(assetIndex);row.dataset.loaded=String(assetIndex>=0);const line=document.createElement('div');line.className='folder-file-row';line.append(row);if(canManage){const remove=document.createElement('button');remove.type='button';remove.className='folder-delete';remove.textContent='SMAZAT';remove.title=`Smazat ${file.name} z GitHubu`;remove.dataset.deleteFile=file.name;remove.dataset.folder=folder.name;remove.dataset.fileSha=file.sha;line.append(remove)}list.append(line)});if(!list.children.length){const empty=document.createElement('p');empty.className='folder-empty';empty.textContent='Zatím bez souborů';list.append(empty)}card.append(list);container.append(card)});
}
function activeMediaFilter(){const choices={cinematic:'contrast(1.1) saturate(1.12) sepia(.08)',contrast:'contrast(1.35) saturate(1.05)',noir:'grayscale(1) contrast(1.28)',film:'sepia(.2) contrast(1.08) saturate(.82)'};return Array.from(document.querySelectorAll('[data-video-filter]:checked')).map(input=>choices[input.dataset.videoFilter]).filter(Boolean).join(' ')||'none'}
function selectedStartSeconds(){return selectedStartFrame/PREVIEW_FPS}
function selectedEndSeconds(){return selectedEndFrame/PREVIEW_FPS}
function effectiveVideoDuration(){return Math.max(1,selectedEndSeconds()-selectedStartSeconds())}
function frameLabel(frame){const whole=Math.floor(frame/PREVIEW_FPS);const minutes=Math.floor(whole/60),seconds=whole%60,subframe=frame%PREVIEW_FPS;return`${String(minutes).padStart(2,'0')}:${String(seconds).padStart(2,'0')}:${String(subframe).padStart(2,'0')}`}
function syncDualRangeTrack(start,maximum){const track=start.closest('.dual-range-track');if(!track)return;const end=track.querySelector('.dual-range-end'),safeMaximum=Math.max(1,maximum),startPercent=maximum?Number(start.value)/safeMaximum*100:0,endPercent=maximum?Number(end.value)/safeMaximum*100:100;track.style.setProperty('--range-start',`${startPercent}%`);track.style.setProperty('--range-end',`${endPercent}%`)}
function syncFrameScrubbers(){
  const asset=selectedAsset();
  const sourceMatches=asset?.type==='video'&&video.src===new URL(asset.src,document.baseURI).href;
  const enabled=sourceMatches&&Number.isFinite(video.duration)&&video.duration>0;
  const maximum=enabled?Math.floor(video.duration*PREVIEW_FPS):0;
  const minGap=Math.min(maximum,5*PREVIEW_FPS);
  if(enabled){
    if(!clipSelectionLoaded){selectedStartFrame=0;selectedEndFrame=maximum;clipSelectionLoaded=true}
    selectedStartFrame=Math.max(0,Math.min(Math.max(0,maximum-minGap),selectedStartFrame));
    selectedEndFrame=Math.max(selectedStartFrame+minGap,Math.min(maximum,selectedEndFrame));
    saveClipSelection();
  }
  for(const id of ['preview','modal']){
    const start=document.getElementById(`${id}-start-frame`),end=document.getElementById(`${id}-end-frame`);
    const startLabel=document.getElementById(`${id}-start-frame-label`),endLabel=document.getElementById(`${id}-end-frame-label`);
    const durationLabel=document.getElementById(`${id}-clip-duration`),controls=document.getElementById(`${id}-video-controls`),play=document.getElementById(`${id}-play-toggle`);
    if(!start||!end)continue;
    controls.hidden=id==='preview'?false:!enabled;
    if(id==='modal')document.getElementById('modal-no-video').hidden=enabled;
    start.disabled=end.disabled=!enabled;start.min=end.min='0';start.max=end.max=String(maximum);
    start.value=String(selectedStartFrame);end.value=String(selectedEndFrame);
    syncDualRangeTrack(start,maximum);
    startLabel.value=startLabel.textContent=frameLabel(selectedStartFrame);endLabel.value=endLabel.textContent=frameLabel(selectedEndFrame);
    durationLabel.value=durationLabel.textContent=formatVideoTime(selectedEndSeconds()-selectedStartSeconds());
    const hint=document.getElementById(`${id}-frame-hint`);
    if(hint)hint.textContent=enabled?`Vybraný úsek z celkové délky ${formatVideoTime(video.duration)}.`:'Nejdřív vyber video v kroku 1.';
    play.disabled=!enabled;play.textContent=previewPlaying?'Ⅱ POZASTAVIT':'▶ PŘEHRÁT SE ZVUKEM';play.setAttribute('aria-label',previewPlaying?'Pozastavit video':'Přehrát video se zvukem');
  }
}
function updateFrameScrubberReadout(){
  for(const id of ['preview','modal']){
    const start=document.getElementById(`${id}-start-frame`),end=document.getElementById(`${id}-end-frame`);
    if(!start||!end)continue;
    start.value=String(selectedStartFrame);end.value=String(selectedEndFrame);
    syncDualRangeTrack(start,Number(start.max));
    const startLabel=document.getElementById(`${id}-start-frame-label`),endLabel=document.getElementById(`${id}-end-frame-label`),durationLabel=document.getElementById(`${id}-clip-duration`);
    startLabel.value=startLabel.textContent=frameLabel(selectedStartFrame);endLabel.value=endLabel.textContent=frameLabel(selectedEndFrame);
    durationLabel.value=durationLabel.textContent=formatVideoTime(selectedEndSeconds()-selectedStartSeconds());
    const hint=document.getElementById(`${id}-frame-hint`);
    if(hint&&Number.isFinite(video.duration))hint.textContent=`Vybraný úsek z celkové délky ${formatVideoTime(video.duration)}.`;
  }
  saveClipSelection();
}
function selectedEndpointSeconds(endpoint='start'){return endpoint==='end'?Math.max(selectedStartSeconds(),selectedEndSeconds()-1/PREVIEW_FPS):selectedStartSeconds()}
function seekSelectedEndpoint(endpoint='start',immediate=false){clearTimeout(pendingSeekTimer);const seek=()=>{pendingSeekTimer=0;lastRangeSeekAt=performance.now();if(video.readyState>=1){try{video.currentTime=selectedEndpointSeconds(endpoint)}catch{}}};const wait=immediate?0:Math.max(0,90-(performance.now()-lastRangeSeekAt));pendingSeekTimer=setTimeout(seek,wait)}
function redrawTextLayout(){if(previewPlaying)setPreviewPlayback(false);drawDesign(canvas);if(!document.getElementById('preview-modal').hidden)drawDesign(document.getElementById('modal-canvas'))}
