async function seekVideoForExport(time){if(!Number.isFinite(video.duration)||video.readyState<1)throw new Error('Zdrojové video ještě není připravené.');if(Math.abs(video.currentTime-time)<.04)return;await new Promise((resolve,reject)=>{const timer=setTimeout(()=>{cleanup();reject(new Error('Nepodařilo se nastavit začátek vybraného úseku.'))},8000);const cleanup=()=>{clearTimeout(timer);video.removeEventListener('seeked',finish);video.removeEventListener('error',fail)};const finish=()=>{cleanup();resolve()};const fail=()=>{cleanup();reject(new Error('Video nelze přesunout na vybraný začátek.'))};video.addEventListener('seeked',finish,{once:true});video.addEventListener('error',fail,{once:true});try{video.currentTime=time}catch{cleanup();reject(new Error('Video nelze přesunout na vybraný začátek.'))}})}
async function captureVideoAudioTrack(){let capture=null;const captureMethod=video.captureStream||video.mozCaptureStream;if(captureMethod){try{capture=captureMethod.call(video);const audio=capture.getAudioTracks().find(track=>track.readyState==='live');if(audio)return{track:audio.clone(),capture}}catch{}}
  const AudioContextClass=window.AudioContext||window.webkitAudioContext;if(!AudioContextClass)return{track:null,capture};
  try{if(!videoAudioContext){videoAudioContext=new AudioContextClass();videoAudioSource=videoAudioContext.createMediaElementSource(video)}videoAudioDestination=videoAudioContext.createMediaStreamDestination();videoAudioSource.connect(videoAudioDestination);if(videoAudioContext.state==='suspended')await videoAudioContext.resume();const audio=videoAudioDestination.stream.getAudioTracks()[0];return{track:audio?.clone()||null,capture}}
  catch{return{track:null,capture}}
}
async function exportVideo(prepareShare=false){if(!canvas.captureStream||!window.MediaRecorder){showToast('Tento prohlížeč nepodporuje export videa z náhledu.');return}const hasSourceVideo=selectedAsset()?.type==='video';const duration=hasSourceVideo?Math.max(1,effectiveVideoDuration()):5;const recorderCanvas=document.createElement('canvas');const spec=formatMap[currentFormat];recorderCanvas.width=spec.width;recorderCanvas.height=spec.height;const stream=recorderCanvas.captureStream(30);let capturedAudio=null,extraAudioTrack=null,recorder=null,running=true;const stopTracks=()=>{for(const track of stream.getTracks())track.stop();if(extraAudioTrack?.readyState==='live')extraAudioTrack.stop();for(const track of capturedAudio?.capture?.getTracks?.()||[])if(track.readyState==='live')track.stop()};
  try{if(hasSourceVideo){if(video.crossOrigin!=='anonymous')video.crossOrigin='anonymous';video.loop=false;video.muted=false;video.volume=1;exportRecording=true;await seekVideoForExport(selectedStartSeconds());capturedAudio=await captureVideoAudioTrack();if(!capturedAudio.track)throw new Error('Ze zdrojového videa se nepodařilo načíst zvukovou stopu. Zkontroluj, že vybraný klip obsahuje zvuk a lze jej přehrát z knihovny.');extraAudioTrack=capturedAudio.track;stream.addTrack(extraAudioTrack);await video.play()}
    const mime=['video/mp4;codecs=avc1.42E01E','video/mp4','video/webm;codecs=vp9,opus','video/webm;codecs=vp8,opus','video/webm'].find(type=>MediaRecorder.isTypeSupported(type));if(!mime)throw new Error('Prohlížeč nepodporuje export videa.');const extension=mime.startsWith('video/mp4')?'mp4':'webm';recorder=new MediaRecorder(stream,{mimeType:mime});const chunks=[];recorder.ondataavailable=event=>{if(event.data.size)chunks.push(event.data)};recorder.onerror=()=>showToast('Při vytváření videa nastala chyba.');recorder.onstop=()=>{running=false;exportRecording=false;video.pause();video.muted=true;video.loop=false;setPreviewPlayback(false);stopTracks();if(chunks.length){const outputBlob=new Blob(chunks,{type:mime});const outputName=`atari-terror-${currentFormat}-${duration}s-${Date.now()}.${extension}`;if(prepareShare){preparedShareBlob=outputBlob;preparedShareFilename=outputName;preparedShareFormat=currentFormat;document.getElementById('share-ready-format').textContent=`${formatMap[preparedShareFormat].title} · ${spec.width} × ${spec.height} PX · ${duration} S · ${extension.toUpperCase()}`;document.getElementById('share-ready-modal').hidden=false;showToast('Výstup je připravený ke sdílení.')}else{downloadBlob(outputBlob,outputName);showToast(`Hotové video se zvukem (${duration} s) se stahuje jako ${extension.toUpperCase()}.`)}}else showToast('Video se nepodařilo vytvořit.')};recorder.start();const startedAt=performance.now();const frame=async now=>{if(!running)return;const elapsed=(now-startedAt)/1000;await drawDesign(recorderCanvas,currentFormat,elapsed);if(elapsed>=duration||hasSourceVideo&&video.currentTime>=selectedEndSeconds()){running=false;if(recorder.state!=='inactive')recorder.stop();return}requestAnimationFrame(frame)};requestAnimationFrame(frame);showToast(prepareShare?'Připravuji výstup pro sociální sítě…':hasSourceVideo?`Vytvářím video se zvukem z vybraného úseku (${duration} s)…`:`Vytvářím ${duration}sekundové video…`)
  }catch(error){running=false;exportRecording=false;video.pause();video.muted=true;video.loop=false;if(recorder&&recorder.state!=='inactive')recorder.stop();else stopTracks();showToast(error.message||'Video se nepodařilo vytvořit.')}}
