function syncPreviewEditor(){const pairs=[['modal-main-headline','main-headline'],['modal-main-headline-size','main-headline-size'],['modal-main-headline-color','main-headline-color'],['modal-post-headline','post-headline'],['modal-headline-size','headline-size'],['modal-content-x','content-x'],['modal-content-y','content-y'],['modal-caption','caption'],['modal-caption-size','caption-size'],['modal-track-select','track-select'],['modal-text-effect','text-effect']];for(const [modalId,sourceId] of pairs){const target=document.getElementById(modalId),source=document.getElementById(sourceId);if(target&&source)target.value=source.value}for(const id of ['main-headline-size','headline-size','caption-size']){const output=document.getElementById(`modal-${id}-value`);if(output)output.value=`${document.getElementById(id).value} %`}document.querySelectorAll('[data-modal-video-filter]').forEach(input=>{const source=document.querySelector(`[data-video-filter="${input.dataset.modalVideoFilter}"]`);input.checked=Boolean(source?.checked)});document.getElementById('modal-preview-format').textContent=formatMap[currentFormat].title;syncEffectButtons(document.getElementById('modal-text-effect').value,'[data-modal-effect]','data-modal-effect')}
for(const [modalId,sourceId] of [['modal-main-headline','main-headline'],['modal-main-headline-size','main-headline-size'],['modal-main-headline-color','main-headline-color'],['modal-post-headline','post-headline'],['modal-headline-size','headline-size'],['modal-content-x','content-x'],['modal-content-y','content-y'],['modal-caption','caption'],['modal-caption-size','caption-size'],['modal-track-select','track-select'],['modal-text-effect','text-effect']]){const modalInput=document.getElementById(modalId),source=document.getElementById(sourceId);modalInput.addEventListener(['modal-track-select','modal-text-effect'].includes(modalId)?'change':'input',()=>{source.value=modalInput.value;source.dispatchEvent(new Event(['modal-track-select','modal-text-effect'].includes(modalId)?'change':'input',{bubbles:true}));if(modalId==='modal-main-headline-size'||modalId==='modal-headline-size'||modalId==='modal-caption-size'){const output=document.getElementById(`modal-${modalId.replace(/^modal-/,'')}-value`);if(output)output.value=`${modalInput.value} %`}})}
